{"name": "create_theme_analyst_role", "query": "
-- ============================================================
-- STEP 1: Create the theme_analyst database role
-- ============================================================
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'theme_analyst') THEN
    CREATE ROLE theme_analyst NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION INHERIT;
  END IF;
END
$$;

-- ============================================================
-- STEP 2: Grant SELECT on reference tables (read-only access)
-- ============================================================

-- Reference tables: full read access
GRANT SELECT ON TABLE public.lego_themes          TO theme_analyst;
GRANT SELECT ON TABLE public.lego_colors          TO theme_analyst;
GRANT SELECT ON TABLE public.lego_parts           TO theme_analyst;
GRANT SELECT ON TABLE public.lego_part_categories TO theme_analyst;

-- Main data tables: read-only access (RLS will further restrict rows)
GRANT SELECT ON TABLE public.lego_sets            TO theme_analyst;
GRANT SELECT ON TABLE public.lego_inventories     TO theme_analyst;
GRANT SELECT ON TABLE public.lego_inventory_parts TO theme_analyst;

-- Explicitly REVOKE any write permissions (defense-in-depth)
REVOKE INSERT, UPDATE, DELETE ON TABLE public.lego_themes          FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON TABLE public.lego_colors          FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON TABLE public.lego_parts           FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON TABLE public.lego_part_categories FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON TABLE public.lego_sets            FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON TABLE public.lego_inventories     FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON TABLE public.lego_inventory_parts FROM theme_analyst;

COMMENT ON ROLE theme_analyst IS 
  'Read-only analyst role restricted to theme-specific LEGO data via RLS policies.';
"}

{"name": "create_get_user_theme_id_function", "query": "
-- ============================================================
-- STEP 3: Create theme assignment function get_user_theme_id()
-- ============================================================
-- This SECURITY DEFINER function returns the theme_id assigned
-- to the current database role. Using SECURITY DEFINER + 
-- set search_path = '' is a Supabase best-practice to prevent
-- privilege escalation and search_path injection attacks.
-- Wrapping calls with (SELECT get_user_theme_id()) in policies
-- causes the Postgres optimizer to cache the result once per
-- query (initPlan), dramatically improving RLS performance.
-- ============================================================

CREATE OR REPLACE FUNCTION public.get_user_theme_id()
RETURNS integer
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_role  TEXT;
  v_theme INT;
BEGIN
  v_role := current_user;

  CASE v_role
    -- Star Wars theme (theme_id = 18)
    WHEN 'theme_analyst' THEN
      v_theme := 18;
    -- Future roles can be added here, e.g.:
    -- WHEN 'city_analyst'    THEN v_theme := 52;
    -- WHEN 'technic_analyst' THEN v_theme := 1;
    -- WHEN 'ninjago_analyst' THEN v_theme := 435;
    ELSE
      -- Superusers / postgres / service_role: no theme restriction
      -- (RLS bypass handles these roles separately)
      v_theme := NULL;
  END CASE;

  RETURN v_theme;
END;
$$;

-- Grant EXECUTE to theme_analyst so the function can be used in RLS policies
GRANT EXECUTE ON FUNCTION public.get_user_theme_id() TO theme_analyst;
-- Also grant to PUBLIC so RLS can evaluate it for any connecting role
GRANT EXECUTE ON FUNCTION public.get_user_theme_id() TO PUBLIC;

COMMENT ON FUNCTION public.get_user_theme_id() IS
  'Returns the theme_id associated with the current database role for RLS enforcement. '
  'Returns 18 (Star Wars) for theme_analyst. Returns NULL for unrestricted roles (postgres, service_role). '
  'Extend the CASE block to support additional analyst roles mapped to their respective themes.';
"}
